<?php
namespace App\Http\Requests\Survey;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class SaveSurveyRequest extends FormRequest
{
 public function authorize():bool{return$this->user()?->hasPermission('surveys.manage')??false;}
 public function rules():array{return['title'=>['required','string','max:255'],'description'=>['nullable','string','max:5000'],'category'=>['required',Rule::in(['employment','farmer','housing','water','health','education','census','general'])],'start_date'=>['required','date'],'end_date'=>['nullable','date','after_or_equal:start_date'],'target_responses'=>['nullable','integer','min:1','max:10000000'],'require_authentication'=>['required','boolean'],'instructions'=>['nullable','string','max:5000'],'language'=>['required','string','max:10'],'village_id'=>['nullable','uuid','exists:villages,id'],'questions'=>['required','array','min:1','max:100'],'questions.*.id'=>['nullable','uuid'],'questions.*.question_text'=>['required','string','max:2000'],'questions.*.question_type'=>['required',Rule::in(['short_text','long_text','number','dropdown','radio','checkbox','date','rating','file_upload','gps_location','mobile'])],'questions.*.options'=>['nullable','array','max:50'],'questions.*.options.*'=>['string','max:255','distinct'],'questions.*.is_required'=>['required','boolean'],'questions.*.validation_rule'=>['nullable','string','max:255'],'questions.*.help_text'=>['nullable','string','max:1000'],'questions.*.category'=>['nullable','string','max:100']];}
 public function after():array{return[function($validator){foreach($this->input('questions',[])as$i=>$question)if(in_array($question['question_type']??'',['dropdown','radio','checkbox'],true)&&count($question['options']??[])<2)$validator->errors()->add("questions.{$i}.options",'At least two options are required.');}];}
}
